-- Simulates an OLD project whose tables were created by hand before database.sql,
-- with foreign keys that do NOT cascade. This is what made account deletion fail
-- with "Database error deleting user".
create table public.profiles (id uuid primary key references auth.users(id), full_name text, email text, role text default 'learner');
create table public.courses (id bigint generated by default as identity primary key, educator_id uuid references public.profiles(id), title text);
create table public.messages (id bigint generated by default as identity primary key, sender_id uuid references public.profiles(id), receiver_id uuid references public.profiles(id), message text, created_at timestamptz default now());
create table public.enrollments (id bigint generated by default as identity primary key, learner_id uuid references public.profiles(id), course_id bigint references public.courses(id), enrolled_at timestamptz default now());
